// Read-only operator history. The bot's short context and delivery pipeline are unchanged.
// Index only recorded fan inputs and final Telegram-acknowledged output, never prompts/raw/generated text.
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";

export const HISTORY_PAGE = 100;
export type HistoryMessage = { id: string; at: string; role: "user" | "assistant"; content: string; delivery: "received" | "acknowledged" | "unverified"; turnId?: string };
type Index = { inode: number; offset: number; byFan: Map<string, Map<string, HistoryMessage>>; badLines: number; firstAt: string | null; busy?: Promise<void> };
const indexes = new Map<string, Index>();
const validChat = (id: string) => /^-?\d{1,16}$/.test(id);

export function messagesForTurn(row: any, identity: string): HistoryMessage[] {
  if (!row || row.mode === "simulated" || !validChat(String(row.chatId)) || !Number.isFinite(Date.parse(row.ts))) return [];
  const at = new Date(row.ts).toISOString();
  const root = typeof row.turnId === "string" ? row.turnId : identity;
  const out: HistoryMessage[] = [];
  const add = (role: HistoryMessage["role"], content: unknown, suffix: string, delivery: HistoryMessage["delivery"]) => {
    if (typeof content === "string" && content.length) out.push({ id: `${root}:${suffix}`, at, role, content, delivery, ...(row.turnId ? { turnId: row.turnId } : {}) });
  };
  add("user", row.fanText, "0", "received");
  const evidence = row.delivery;
  const acknowledged = [evidence?.text, evidence?.media, evidence?.recovery].some(a => a?.status === "acknowledged");
  const finals: string[] = !evidence || acknowledged ? (Array.isArray(row.final) ? row.final.filter((s: unknown) => typeof s === "string") : []) : [];
  const media = row.media && (!evidence || evidence.media?.status === "acknowledged") ? row.media : null;
  const note = media ? (media.free ? `[sent him free ${media.kind}: ${media.label}]` : `[locked ${media.kind} waiting for him to unlock: ${media.label}]`) : "";
  if (note && !finals.length) finals.push("");
  finals.forEach((s, i) => add("assistant", [s, i === 0 ? note : ""].filter(Boolean).join("\n"), `1:${String(i).padStart(4, "0")}`, evidence ? "acknowledged" : "unverified"));
  if (row.tip?.sent?.status === "acknowledged") add("assistant", row.tip.text, "2", "acknowledged");
  return out;
}

/** Incremental byte-offset scan, one shared scan per creator. Partial final lines are retried next time. */
async function refresh(file: string, index: Index, now: number): Promise<void> {
  let stat: fs.Stats;
  try { stat = await fs.promises.stat(file); } catch (e: any) { if (e.code === "ENOENT") return; throw e; }
  if (stat.ino !== index.inode || stat.size < index.offset) { index.inode = stat.ino; index.offset = 0; }
  if (stat.size > index.offset) {
    let pending = Buffer.alloc(0), consumed = index.offset;
    const stream = fs.createReadStream(file, { start: index.offset, end: stat.size - 1, highWaterMark: 64 * 1024 });
    for await (const chunk of stream) {
      pending = Buffer.concat([pending, chunk as Buffer]);
      let start = 0, end: number;
      while ((end = pending.indexOf(10, start)) >= 0) {
        const line = pending.subarray(start, end); consumed += end - start + 1; start = end + 1;
        if (!line.length) continue;
        let row: any;
        try { row = JSON.parse(line.toString("utf8")); } catch { index.badLines++; continue; }
        if (row.mode === "simulated" || !validChat(String(row.chatId))) continue;
        const ts = Date.parse(row.ts);
        if (!Number.isFinite(ts)) continue;
        const at = new Date(ts).toISOString();
        if (!index.firstAt || at < index.firstAt) index.firstAt = at;
        if (ts > now) continue;
        const id = createHash("sha256").update(line).digest("hex");
        const messages = messagesForTurn(row, id);
        if (!messages.length) continue;
        const fan = String(row.chatId), target = index.byFan.get(fan) ?? new Map<string, HistoryMessage>();
        for (const message of messages) target.set(message.id, message);
        index.byFan.set(fan, target);
      }
      pending = pending.subarray(start);
      index.offset = consumed;
    }
  }
}

export function pageHistory(messages: HistoryMessage[], before: string | null, now = Date.now()) {
  let cursor: { at: string; id: string } | null = null;
  if (before) {
    try { cursor = JSON.parse(Buffer.from(before, "base64url").toString("utf8")); } catch { throw new Error("Invalid history cursor"); }
    if (!cursor || typeof cursor.at !== "string" || !Number.isFinite(Date.parse(cursor.at)) || typeof cursor.id !== "string" || cursor.id.length > 200) throw new Error("Invalid history cursor");
  }
  const until = new Date(now).toISOString();
  const available = messages.filter(m => m.at <= until);
  const from = available.reduce((first, message) => message.at < first ? message.at : first, until);
  const all = available.filter(m => !cursor || m.at < cursor.at || (m.at === cursor.at && m.id < cursor.id))
    .sort((a, b) => a.at < b.at ? -1 : a.at > b.at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  const history = all.slice(-HISTORY_PAGE), hasMore = all.length > HISTORY_PAGE;
  const oldest = history[0];
  return { history, hasMore, nextCursor: hasMore && oldest ? Buffer.from(JSON.stringify({ at: oldest.at, id: oldest.id })).toString("base64url") : null, from, until, days: null, scope: "all-stored" as const };
}

export async function chatHistory(logDir: string, chatId: string, before: string | null = null, now = Date.now()) {
  if (!validChat(chatId)) throw new Error("Invalid chat id");
  if (before && before.length > 600) throw new Error("Invalid history cursor");
  const file = path.resolve(logDir, "requests.jsonl");
  let index = indexes.get(file);
  if (!index) { index = { inode: 0, offset: 0, byFan: new Map(), badLines: 0, firstAt: null }; indexes.set(file, index); }
  if (!index.busy) index.busy = refresh(file, index, now).finally(() => { index!.busy = undefined; });
  await index.busy;
  return { ...pageHistory([...index.byFan.get(chatId)?.values() ?? []], before, now),
    source: "retained-turn-logs", earliestRecordedAt: index.firstAt,
    incompleteLines: index.badLines, note: "All retained message history. Messages that were never saved cannot be restored." };
}

// Paged history shared by both operator chat views. No writes or bot actions.
window.createHistoryView = function (getPage, changed) {
  var state = { id: '', history: [], ready: false, loading: false, error: '', nextCursor: null, incompleteLines: 0 };
  var generation = 0;
  function load(older) {
    if (!state.id || state.loading || (older && !state.nextCursor)) return Promise.resolve();
    var token = generation, id = state.id, cursor = older ? state.nextCursor : null;
    state.loading = true; state.error = ''; changed('loading');
    return getPage(id, cursor).then(function (page) {
      if (token !== generation) return;
      if (!page || !Array.isArray(page.history) || page.error) throw new Error('History unavailable');
      var previousLast = state.history[state.history.length - 1], firstNew = page.history[0];
      var gap = previousLast && firstNew && (previousLast.at < firstNew.at || previousLast.at === firstNew.at && previousLast.id < firstNew.id);
      var seen = new Map();
      state.history.concat(page.history).forEach(function (m) { if (m.at >= page.from && m.at <= page.until) seen.set(m.id, m); });
      state.history = Array.from(seen.values()).sort(function (a, b) { return a.at < b.at ? -1 : a.at > b.at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0; });
      if (older || !state.ready || !state.nextCursor && gap && page.nextCursor) state.nextCursor = page.nextCursor;
      state.ready = true; state.loading = false; state.incompleteLines = page.incompleteLines || 0;
      changed(older ? 'older' : 'latest');
    }).catch(function () {
      if (token !== generation) return;
      state.loading = false; state.error = 'Could not load older history. Retry.'; changed('error');
    });
  }
  return {
    state: state,
    select: function (id) {
      if (String(id || '') === state.id) return;
      generation++; state.id = String(id || ''); state.history = []; state.ready = false;
      state.loading = false; state.error = ''; state.nextCursor = null; state.incompleteLines = 0;
      return load(false);
    },
    refresh: function () { return load(false); },
    older: function () { return load(true); },
    controls: function () {
      var msg = state.error || (state.loading ? 'Loading history...' : 'All stored history');
      return '<div class="center" style="padding:10px;text-align:center"><span class="daypill">' + msg + '</span> ' +
        (state.nextCursor ? '<button data-history-older' + (state.loading ? ' disabled' : '') + '>Older messages</button> ' : '') +
        '<button data-history-latest' + (state.loading ? ' disabled' : '') + '>Refresh latest</button>' +
        (state.incompleteLines ? '<div>Some log records could not be read.</div>' : '') +
        (!state.history.length && !state.loading ? '<div>Recent saved messages below have no recorded dates.</div>' : '') + '</div>';
    },
    bind: function (element) {
      var old = element.querySelector('[data-history-older]'), fresh = element.querySelector('[data-history-latest]');
      if (old) old.onclick = function () { load(true); };
      if (fresh) fresh.onclick = function () { load(false); };
    }
  };
};

import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import vm from "node:vm";
import { chatHistory, messagesForTurn, pageHistory } from "../dashboard/history.js";
const now = Date.parse("2026-10-12T03:00:00Z");
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "history-window-"));
const make = (i: number, chatId = 123) => ({ ts: new Date(now - 1000000 + i).toISOString(), chatId, turnId: `turn-${i}`, fanText: `fan ${i}`, final: [`reply ${i}`], raw: "DO NOT DISPLAY", system: "PRIVATE PROMPT", delivery: { text: { status: "acknowledged" } } });
try {
  const a = path.join(dir, "creator-a"), b = path.join(dir, "creator-b"); fs.mkdirSync(a); fs.mkdirSync(b);
  const records = Array.from({ length: 251 }, (_, i) => make(i));
  records.push({ ...make(300), ts: new Date(now - 91 * 86400_000).toISOString() });
  records.push({ ...make(301), mode: "simulated" } as any);
  records.push(make(302, 999));
  fs.writeFileSync(path.join(a, "requests.jsonl"), records.map(r => JSON.stringify(r)).join("\n") + "\n");
  fs.writeFileSync(path.join(b, "requests.jsonl"), JSON.stringify({ ...make(0), final: ["other creator"] }) + "\n");
  let page = await chatHistory(a, "123", null, now), all = [...page.history];
  assert.equal(page.history.length, 100); assert.equal(page.hasMore, true);
  while (page.nextCursor) { page = await chatHistory(a, "123", page.nextCursor, now); all = [...page.history, ...all]; }
  assert.equal(all.length, 504); assert.equal(new Set(all.map(m => m.id)).size, 504);
  assert.equal(all[0].content, "fan 300", "Messages older than 90 days remain available"); assert.equal(all.at(-1)!.content, "reply 250");
  assert.equal(page.scope, "all-stored"); assert.equal(page.days, null);
  assert.equal(page.from, new Date(now - 91 * 86400_000).toISOString());
  assert(!JSON.stringify(all).includes("PRIVATE PROMPT")); assert(!JSON.stringify(all).includes("DO NOT DISPLAY"));
  assert.equal((await chatHistory(b, "123", null, now)).history.at(-1)!.content, "other creator");
  assert(!all.some(m => m.content === "other creator" || m.content === "fan 302"));
  const unicode = { ...make(400), final: ["Hello 💙 café"] }, line = JSON.stringify(unicode);
  fs.appendFileSync(path.join(a, "requests.jsonl"), line.slice(0, -4));
  assert.equal((await chatHistory(a, "123", null, now)).history.at(-1)!.content, "reply 250");
  fs.appendFileSync(path.join(a, "requests.jsonl"), line.slice(-4) + "\nnot-json\n");
  page = await chatHistory(a, "123", null, now); assert.equal(page.history.at(-1)!.content, "Hello 💙 café"); assert.equal(page.incompleteLines, 1);
  assert.equal((await chatHistory(a, "123", null, now)).history.filter(m => m.content === "Hello 💙 café").length, 1);
  const rejected = messagesForTurn({ ...make(500), delivery: { text: { status: "rejected" } } }, "bad");
  assert.deepEqual(rejected.map(m => m.role), ["user"]);
  const unknown = messagesForTurn({ ...make(501), delivery: { text: { status: "unknown" } } }, "unknown");
  assert.equal(unknown.length, 1);
  assert.equal(messagesForTurn({ ...make(502), delivery: undefined }, "legacy")[1].delivery, "unverified");
  const media = messagesForTurn({ ...make(503), final: [], media: { kind: "photo", label: "image", free: false }, delivery: { media: { status: "acknowledged" } } }, "media");
  assert.match(media[1].content, /locked photo/);
  const tied = all.map(m => ({ ...m, at: "2026-10-12T02:00:00.000Z" })); let p = pageHistory(tied, null, now), ids = p.history.map(m => m.id);
  while (p.nextCursor) { p = pageHistory(tied, p.nextCursor, now); ids.push(...p.history.map(m => m.id)); } assert.equal(new Set(ids).size, 504);
  const later = await chatHistory(b, "123", null, now + 366 * 86400_000);
  assert.equal(later.history.length, 2, "Indexed messages must not expire with age");
  await assert.rejects(chatHistory(a, "../123", null, now)); await assert.rejects(chatHistory(a, "123", "invalid", now));
  const events: string[] = [], context: any = { Map, Promise }; context.window = context;
  vm.createContext(context); vm.runInContext(fs.readFileSync(new URL("../dashboard/history-client.js", import.meta.url), "utf8"), context);
  let release: (value: any) => void = () => {};
  const client = context.createHistoryView((id: string) => id === "123" ? new Promise(resolve => { release = resolve; }) : Promise.resolve({ history: [{ ...all[0], id: "other", content: "new fan" }], from: "2026-07-01", until: "2026-10-13", nextCursor: null }), (s: string) => events.push(s));
  const first = client.select("123"); await client.select("456"); release({ history: all, from: "2026-07-01", until: "2026-10-13" }); await first;
  assert.equal(client.state.id, "456"); assert.equal(client.state.history.length, 1); assert.equal(client.state.history[0].content, "new fan");
  await client.refresh(); assert.equal(client.state.history.length, 1); assert(events.includes("latest"));
  console.log("All stored V2 history: no age cutoff or expiry, paging, Unicode/partial appends, delivery evidence, creator/fan isolation, cursor validation and stale UI responses passed.");
} finally { fs.rmSync(dir, { recursive: true, force: true }); }
